window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8dcaccf0f99f30f0"]={"versions": [{"id": "FIG-8dcaccf0f99f30f0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}, {"id": "FIG-7536397c800ca1b7", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}, {"id": "FIG-3ec3f4b9b8973df7", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}, {"id": "FIG-e85d4962031c16dc", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}, {"id": "FIG-25b2bfb34c8d1204", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}, {"id": "FIG-7a8fce73d39f36bf", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des synchronen Steuerflusses zur unmittelbaren Software-Manipulation eines I/O-Pins über den Output Compare Unit (OCU) Treiber. Es demonstriert die Entkopplung von regulären zeitbasierten Hardware-Vergleichsereignissen (Compare-Match-Aktionen), indem der Pin-Pegel synchron und deterministisch per API-Aufruf forciert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Lifelines:</strong></li>\n<li><code>OcuUser</code>: Aufrufende Schicht bzw. Software-Entität oberhalb des MCAL (z. B. Complex Device Driver (CDD), I/O Hardware Abstraction oder SWC via BSW/RTE).</li>\n<li><code>«module» Ocu</code>: MCAL-Treibermodul der Output Compare Unit gemäß AUTOSAR-Basissoftware-Architektur.</li>\n<li><code>«peripheral» Ocu pin</code>: Physikalische Mikrocontroller-Peripherie / I/O-Pad bzw. dedizierter Output-Compare-Kanalpin des Timermoduls.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Ocu_SetPinState(ChannelNumber, PinState)</code>:</li>\n<li><code>ChannelNumber</code> (<code>Ocu_ChannelType</code>): Numerische ID des Zielkanals.</li>\n<li><code>PinState</code> (<code>Ocu_PinStateType</code>): Zu setzender logischer Pegel (<code>OCU_HIGH</code> / <code>OCU_LOW</code>).</li>\n<li><strong>Strukturierte Beziehungen:</strong></li>\n<li>Direkter Kontrollfluss: <code>OcuUser</code> nutzt die Treiber-API von <code>Ocu</code>.</li>\n<li>Hardware-Abstraktion: <code>Ocu</code> bedient unmittelbar die Register der Peripherie (<code>«peripheral»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>OcuUser</code> initiiert den synchronen Funktionsaufruf <code>Ocu_SetPinState(ChannelNumber, PinState)</code>.</li>\n<li><strong>Treiber-Ausführung:</strong> Das Modul <code>Ocu</code> validiert (bei aktivem DET) Initialisierungsstatus und Parametergrenzen und schreibt die entsprechenden Pegelbits direkt in das Register der Zielperipherie.</li>\n<li><strong>Hardware-Aktion:</strong> Die Hardware übernimmt die Konfiguration ohne Wartezeit auf ein Zählerereignis (<em>„Pin level changed immediately“</em>).</li>\n<li><strong>Rückkehr:</strong> Unmittelbare synchrone Rückkehr des Kontrollflusses über <code>Ocu</code> an den Aufrufer <code>OcuUser</code> (kein asynchrones Polling, kein Callback).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor-Konfiguration:</strong> Die Verfügbarkeit der Funktion wird typischerweise über den Konfigurationsparameter <code>OcuSetPinStateApi</code> (<code>STD_ON</code> / <code>STD_OFF</code>) geschaltet. Ist das Feature deaktiviert, existiert das API-Symbol nicht im Treiber-Header.</li>\n<li><strong>Hardware-Voraussetzung:</strong> Der Kanal muss hardwareseitig für Pin-Aktionen ausgelegt sein (<code>OcuHwSpecificPinHandling</code> bzw. Vorhandensein eines physischen Ausgangspins auf dem jeweiligen Timer/OCU-Kanal).</li>\n<li><strong>Laufzeit- & Reentrancy-Bedingungen:</strong></li>\n<li>Reentrant für unterschiedliche Kanäle (<code>ChannelNumber</code>); non-reentrant für denselben Kanal.</li>\n<li>Darf nur aufgerufen werden, wenn der OCU-Treiber vollständig initialisiert ist (<code>Ocu_Init</code>). Ein Aufruf im uninitialisierten Zustand erzeugt den Fehler <code>OCU_E_UNINIT</code> via Default Error Tracer (DET).</li>\n<li><strong>Interaktion mit Compare-Events:</strong> Das Forcieren des Pin-Zustands setzt den physikalischen Pegel sofort, beeinflusst jedoch nicht den internen Zählerstand oder das geplante Eintreffen nachfolgender Match-Ereignisse (sofern nicht anders im Hardware-Handbuch spezifiziert).</li>\n</ul>"}], "trans": [{"from": "FIG-8dcaccf0f99f30f0", "to": "FIG-7536397c800ca1b7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7536397c800ca1b7", "to": "FIG-3ec3f4b9b8973df7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3ec3f4b9b8973df7", "to": "FIG-e85d4962031c16dc", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e85d4962031c16dc", "to": "FIG-25b2bfb34c8d1204", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-25b2bfb34c8d1204", "to": "FIG-7a8fce73d39f36bf", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Gesamtdiagramm: Redaktionelle Überarbeitung von Layout und Typografie (geänderte Schriftart, angepasste Skalierung und Boxenproportionen ohne semantische Änderung).</li>\n</ul>"}]};
